//! Tests for `text/template/parse`: Go's parse_test.go and lex_test.go tables
//! (replayed from fixtures generated by the Go toolchain) and API checks.

#[path = "../examples/common/template_harness.rs"]
mod harness;

use rust_stdlib::text::template::parse::{
    self, is_empty_tree, Mode, Node, NodeType, Tree, PARSE_COMMENTS, SKIP_FUNC_CHECK,
};
use std::collections::{BTreeMap, HashMap};

fn funcs(names: &[&str]) -> HashMap<String, ()> {
    names.iter().map(|n| ((*n).to_owned(), ())).collect()
}

fn parse_str(name: &str, text: &str, f: &HashMap<String, ()>) -> Result<Tree, parse::Error> {
    let mut t = Tree::new(name);
    let mut set = BTreeMap::new();
    t.parse(text, "", "", &mut set, &[f])?;
    Ok(t)
}

/// Every input of Go's parse and lex tests gets Go's result: the tree's
/// string form, or the error text.
#[test]
fn fixtures_match_go() {
    let n = harness::replay("parse.jsonl");
    assert!(n > 250, "only {n} parse fixtures replayed");
}

#[test]
fn is_empty_tree_table() {
    // Go's isEmptyTests.
    let cases = [
        ("empty", "", true),
        ("nonempty", "hello", false),
        ("spaces only", " \t\n \t\n", true),
        ("comment only", "{{/* comment */}}", true),
        ("definition", r#"{{define "x"}}something{{end}}"#, true),
        (
            "definitions and space",
            "{{define `x`}}something{{end}}\n\n{{define `y`}}something{{end}}\n\n",
            true,
        ),
        (
            "definitions and text",
            "{{define `x`}}something{{end}}\nx\n{{define `y`}}something{{end}}\ny\n",
            false,
        ),
        (
            "definition and action",
            "{{define `x`}}something{{end}}{{if 3}}foo{{end}}",
            false,
        ),
    ];
    assert!(is_empty_tree(None), "nil tree is not empty");
    for (name, input, empty) in cases {
        let tree = parse_str("root", input, &funcs(&[])).unwrap_or_else(|e| panic!("{name}: {e}"));
        let root = Node::List(tree.root.clone().expect("root"));
        assert_eq!(is_empty_tree(Some(&root)), empty, "{name}");
    }
}

#[test]
#[allow(clippy::type_complexity)]
fn number_node_table() {
    // Go's numberTests: (text, isInt, isUint, isFloat, isComplex, int64, uint64, float64, complex).
    #[rustfmt::skip]
    let cases: &[(&str, bool, bool, bool, bool, i64, u64, f64, (f64, f64))] = &[
        ("0", true, true, true, false, 0, 0, 0.0, (0.0, 0.0)),
        ("-0", true, true, true, false, 0, 0, 0.0, (0.0, 0.0)),
        ("73", true, true, true, false, 73, 73, 73.0, (0.0, 0.0)),
        ("7_3", true, true, true, false, 73, 73, 73.0, (0.0, 0.0)),
        ("0b10_010_01", true, true, true, false, 73, 73, 73.0, (0.0, 0.0)),
        ("0B10_010_01", true, true, true, false, 73, 73, 73.0, (0.0, 0.0)),
        ("073", true, true, true, false, 0o73, 0o73, 59.0, (0.0, 0.0)),
        ("0o73", true, true, true, false, 0o73, 0o73, 59.0, (0.0, 0.0)),
        ("0O73", true, true, true, false, 0o73, 0o73, 59.0, (0.0, 0.0)),
        ("0x73", true, true, true, false, 0x73, 0x73, 115.0, (0.0, 0.0)),
        ("0X73", true, true, true, false, 0x73, 0x73, 115.0, (0.0, 0.0)),
        ("0x7_3", true, true, true, false, 0x73, 0x73, 115.0, (0.0, 0.0)),
        ("-73", true, false, true, false, -73, 0, -73.0, (0.0, 0.0)),
        ("+73", true, false, true, false, 73, 0, 73.0, (0.0, 0.0)),
        ("100", true, true, true, false, 100, 100, 100.0, (0.0, 0.0)),
        ("1e9", true, true, true, false, 1_000_000_000, 1_000_000_000, 1e9, (0.0, 0.0)),
        ("-1e9", true, false, true, false, -1_000_000_000, 0, -1e9, (0.0, 0.0)),
        ("-1.2", false, false, true, false, 0, 0, -1.2, (0.0, 0.0)),
        ("1e19", false, true, true, false, 0, 10_000_000_000_000_000_000, 1e19, (0.0, 0.0)),
        ("1e1_9", false, true, true, false, 0, 10_000_000_000_000_000_000, 1e19, (0.0, 0.0)),
        ("1E19", false, true, true, false, 0, 10_000_000_000_000_000_000, 1e19, (0.0, 0.0)),
        ("-1e19", false, false, true, false, 0, 0, -1e19, (0.0, 0.0)),
        ("0x_1p4", true, true, true, false, 16, 16, 16.0, (0.0, 0.0)),
        ("0X_1P4", true, true, true, false, 16, 16, 16.0, (0.0, 0.0)),
        ("0x_1p-4", false, false, true, false, 0, 0, 1.0 / 16.0, (0.0, 0.0)),
        ("4i", false, false, false, true, 0, 0, 0.0, (0.0, 4.0)),
        ("-1.2+4.2i", false, false, false, true, 0, 0, 0.0, (-1.2, 4.2)),
        ("073i", false, false, false, true, 0, 0, 0.0, (0.0, 73.0)),
        ("0i", true, true, true, true, 0, 0, 0.0, (0.0, 0.0)),
        ("-1.2+0i", false, false, true, true, 0, 0, -1.2, (-1.2, 0.0)),
        ("-12+0i", true, false, true, true, -12, 0, -12.0, (-12.0, 0.0)),
        ("13+0i", true, true, true, true, 13, 13, 13.0, (13.0, 0.0)),
        ("0123", true, true, true, false, 0o123, 0o123, 83.0, (0.0, 0.0)),
        ("-0x0", true, true, true, false, 0, 0, 0.0, (0.0, 0.0)),
        ("0xdeadbeef", true, true, true, false, 0xdeadbeef, 0xdeadbeef, 3735928559.0, (0.0, 0.0)),
        ("'a'", true, true, true, false, 97, 97, 97.0, (0.0, 0.0)),
        ("'\\n'", true, true, true, false, 10, 10, 10.0, (0.0, 0.0)),
        ("'\\\\'", true, true, true, false, 92, 92, 92.0, (0.0, 0.0)),
        ("'\\''", true, true, true, false, 39, 39, 39.0, (0.0, 0.0)),
        ("'\\xFF'", true, true, true, false, 255, 255, 255.0, (0.0, 0.0)),
        ("'\u{30d1}'", true, true, true, false, 0x30d1, 0x30d1, 12497.0, (0.0, 0.0)),
        ("'\\u30d1'", true, true, true, false, 0x30d1, 0x30d1, 12497.0, (0.0, 0.0)),
        ("'\\U000030d1'", true, true, true, false, 0x30d1, 0x30d1, 12497.0, (0.0, 0.0)),
        ("0xef", true, true, true, false, 0xef, 0xef, 239.0, (0.0, 0.0)),
    ];
    for &(text, is_int, is_uint, is_float, is_complex, i, u, f, (re, im)) in cases {
        let tree = parse_str("n", &format!("{{{{{text}}}}}"), &funcs(&[]))
            .unwrap_or_else(|e| panic!("{text}: {e}"));
        let root = tree.root.as_ref().expect("root");
        let Node::Action(a) = &root.nodes[0] else {
            panic!("{text}: not an action")
        };
        let Node::Number(n) = &a.pipe.cmds[0].args[0] else {
            panic!("{text}: not a number")
        };
        assert_eq!(n.text, text);
        assert_eq!(n.is_complex, is_complex, "{text} complex");
        assert_eq!(
            (n.is_int, n.is_uint, n.is_float),
            (is_int, is_uint, is_float),
            "{text}"
        );
        if is_int {
            assert_eq!(n.int64, i, "{text} int64");
        }
        if is_uint {
            assert_eq!(n.uint64, u, "{text} uint64");
        }
        if is_float {
            assert_eq!(n.float64, f, "{text} float64");
        }
        if is_complex {
            assert_eq!(
                (n.complex128.re, n.complex128.im),
                (re, im),
                "{text} complex128"
            );
        }
    }
    // Some broken syntax.
    for text in [
        "+-2",
        "0x123.",
        "1e.",
        "0xi.",
        "1+2.",
        "'x",
        "'xx'",
        "'433937734937734969526500969526500'",
    ] {
        assert!(
            parse_str("n", &format!("{{{{{text}}}}}"), &funcs(&[])).is_err(),
            "{text} should not parse"
        );
    }
}

#[test]
fn keywords_and_funcs() {
    // When a break function is provided, the parser treats break as a function.
    let src = "{{range .X}}{{break 20}}{{end}}";
    assert!(parse_str("", src, &funcs(&["break"])).is_ok());
    let err = parse_str("", src, &funcs(&[])).unwrap_err();
    assert!(
        err.to_string().contains("unexpected \"20\" in {{break}}"),
        "{err}"
    );
}

#[test]
fn skip_func_check() {
    let mut tr = Tree::new("skip func check");
    tr.mode = SKIP_FUNC_CHECK;
    let mut set = BTreeMap::new();
    tr.parse("{{fn 1 2}}", "", "", &mut set, &[]).unwrap();
    assert_eq!(tr.root.as_ref().unwrap().to_string(), "{{fn 1 2}}");
    assert!(parse_str("x", "{{fn 1 2}}", &funcs(&[])).is_err());
}

#[test]
fn comments_are_kept_only_on_request() {
    let mut tr = Tree::new("comment");
    tr.mode = PARSE_COMMENTS;
    let mut set = BTreeMap::new();
    tr.parse("x \r\n\t{{- /* hi */}}", "", "", &mut set, &[])
        .unwrap();
    assert_eq!(tr.root.as_ref().unwrap().to_string(), "x{{/* hi */}}");
    let t = parse_str("c", "{{/* hi */}}", &funcs(&[])).unwrap();
    assert_eq!(t.root.as_ref().unwrap().to_string(), "");
    assert_eq!(Mode(0).0 | PARSE_COMMENTS.0 | SKIP_FUNC_CHECK.0, 3);
}

#[test]
fn error_context_with_tree_copy() {
    let tree = parse_str("root", "{{if true}}{{end}}", &funcs(&[])).unwrap();
    let copy = tree.copy();
    let n0 = &tree.root.as_ref().unwrap().nodes[0];
    let n1 = &copy.root.as_ref().unwrap().nodes[0];
    assert_eq!(tree.error_context(n0), copy.error_context(n1));
    assert_eq!(tree.error_context(n0).0, "root:1:5");
    assert_eq!(copy.mode, Mode(0), "Copy discards the parse mode");
}

#[test]
fn block_defines_and_invokes() {
    let mut set = BTreeMap::new();
    let mut tr = Tree::new("outer");
    tr.parse(
        r#"a{{block "inner" .}}bar{{.}}baz{{end}}b"#,
        "",
        "",
        &mut set,
        &[],
    )
    .unwrap();
    assert_eq!(
        tr.root.as_ref().unwrap().to_string(),
        r#"a{{template "inner" .}}b"#
    );
    assert_eq!(
        set["inner"].root.as_ref().unwrap().to_string(),
        "bar{{.}}baz"
    );
    assert!(set.contains_key("outer"));
}

#[test]
fn line_numbers() {
    let text = "{{printf 1234}}\n".repeat(3);
    let tree = parse_str("bench", &text, &funcs(&["printf"])).unwrap();
    let nodes = &tree.root.as_ref().unwrap().nodes;
    for i in (0..nodes.len()).step_by(2) {
        let line = 1 + i / 2;
        let Node::Action(a) = &nodes[i] else {
            panic!("not an action")
        };
        assert_eq!(a.line, line, "action line");
        assert_eq!(a.pipe.line, line, "pipe line");
    }
}

#[test]
fn max_expression_depth() {
    // Go's tests lower maxStackDepth to 3.
    for (src, ok) in [
        ("{{ (( 1 )) }}", true),
        ("{{ ((( 1 ))) }}", true),
        ("{{ (((( 1 )))) }}", false),
        ("{{ ((( 1 ))) | printf }}", true),
        ("{{ (((( 1 )))) | printf }}", false),
    ] {
        let mut set = BTreeMap::new();
        let mut t = Tree::new("test");
        t.set_max_expression_depth(3);
        let r = t.parse(src, "", "", &mut set, &[&funcs(&["printf"])]);
        assert_eq!(r.is_ok(), ok, "{src}");
        if !ok {
            assert_eq!(
                r.unwrap_err().to_string(),
                "template: test:1: max expression depth exceeded"
            );
        }
    }
}

#[test]
fn node_types_and_positions() {
    let tree = parse_str("t", "ab{{.X}}{{if 1}}y{{end}}", &funcs(&[])).unwrap();
    let nodes = &tree.root.as_ref().unwrap().nodes;
    let types: Vec<NodeType> = nodes.iter().map(Node::node_type).collect();
    assert_eq!(types, [NodeType::Text, NodeType::Action, NodeType::If]);
    assert_eq!(nodes[1].position(), parse::Pos(4));
    assert_eq!(NodeType::List as i32, 11);
    assert_eq!(NodeType::Comment as i32, 20);
    assert_eq!(NodeType::Continue as i32, 22);
    // String forms and Copy round-trip.
    assert_eq!(
        nodes[2].to_string(),
        "{{if 1}}\"y\"{{end}}".replace('"', "")
    );
    assert_eq!(nodes[2].copy().to_string(), nodes[2].to_string());
}

#[test]
fn package_parse_returns_every_definition() {
    let trees = parse::parse(
        "main",
        r#"{{define "a"}}A{{end}}{{define "b"}}B{{end}}main"#,
        "",
        "",
        &[],
    )
    .unwrap();
    let names: Vec<&String> = trees.keys().collect();
    assert_eq!(names, ["a", "b", "main"]);
}

#[test]
fn multiple_definitions_are_rejected() {
    let err = parse_str(
        "t",
        r#"{{define "x"}}a{{end}}{{define "x"}}b{{end}}"#,
        &funcs(&[]),
    )
    .unwrap_err();
    assert_eq!(
        err.to_string(),
        r#"template: t:1: template: multiple definition of template "x""#
    );
}

#[test]
fn identifier_node_and_chain_add() {
    let id = parse::IdentifierNode::new("fn").set_pos(parse::Pos(3));
    assert_eq!(id.to_string(), "fn");
    assert_eq!(id.position(), parse::Pos(3));
    assert_eq!(id.node_type(), NodeType::Identifier);
}
